const p = $json.body || {};
const body = String(p.body || '').trim().slice(0, 12000);
const operator = String(p.operator || 'Operador Firefox').replace(/\s+/g, ' ').trim().slice(0, 160);
return { body, operator: operator || 'Operador Firefox', timestampIso: String(p.timestampIso || new Date().toISOString()), pageUrl: String(p.pageUrl || '').slice(0, 2000), pageTitle: String(p.pageTitle || '').slice(0, 500) };

function textoOpenAI(obj) {
  if (Array.isArray(obj.output) && obj.output[0]?.content?.[0]?.text) return obj.output[0].content[0].text;
  if (obj.content?.[0]?.text) return obj.content[0].text;
  if (obj.message?.content) return obj.message.content;
  return obj.output_text || obj.text || '';
}
const base = $('Normalizar captura').first().json;
const raw = String(textoOpenAI($json)).replace(/^```json/i, '').replace(/^```/i, '').replace(/```$/i, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch { return { listo: false, message: 'La IA devolvió una respuesta inválida. Cargá el caso manualmente.' }; }
const motivos = new Set(['SEGUIMIENTO', 'ENTREGAR EN ESTA UBICACION', 'DIRECCION Y NUMERO', 'NUMERO ALTERNO', 'INDICACIONES', 'DOMICILIO ALTERNO', 'NO ESTAN EN CEDIS', 'SINIESTRADO']);
const idPedido = String(parsed.idPedido || '').trim();
const reclamoTienda = String(parsed.reclamoTienda || '').trim().toUpperCase();
const ubicacion = String(parsed.ubicacion || '').trim();
const telefono = String(parsed.telefono || '').trim();
const confianza = Number(parsed.confianza || 0);
const motivoRevision = String(parsed.motivoRevision || '').trim();
const tieneDato = Boolean(ubicacion || telefono || ['NO ESTAN EN CEDIS', 'SINIESTRADO'].includes(reclamoTienda));
const listo = /^\d{7,9}$/.test(idPedido) && motivos.has(reclamoTienda) && tieneDato && confianza >= 0.75 && parsed.requiereRevision !== true;
return { listo, idPedido, reclamoTienda, ubicacion, telefono, confianza, operator: base.operator, message: listo ? '' : (motivoRevision || 'No se pudo identificar con suficiente certeza el pedido y los datos de la tienda.') };

const interpretado = $('Validar interpretación').first().json;
if (!$json.id) return { ok: false, httpStatus: 404, message: `El pedido ${interpretado.idPedido} no está en el período operativo.` };
return { ok: true, httpStatus: 200, id: String($json.id), message: `Pedido ${$json.id} actualizado: ${$json.reclamo_tienda}.` };
